const RANKS=[{name:`Bronze`,min:100},{name:`Silver`,min:250},{name:`Gold`,min:400},{name:`Scholar`,min:550},{name:`Master`,min:700},{name:`Grandmaster`,min:850}];
function rankInfo(v){let rating=Math.max(100,Math.min(1000,Number(v)||180)),rank=RANKS[0];for(const r of RANKS)if(rating>=r.min)rank=r;let ix=RANKS.indexOf(rank),next=RANKS[ix+1];return{name:rank.name,rating,progress:next?Math.round((rating-rank.min)/(next.min-rank.min)*100):100}}
function missionInfo(game){let number=(game?.missions||0)+1,boss=number%5===0,rank=rankInfo(game?.rating),tier=Math.max(1,Math.min(6,1+Math.floor((rank.rating-100)/150)));return{number,boss,rank,tier,nextBoss:boss?0:5-number%5,label:boss?`Recurring Boss`:[`Mixed audit`,`Weak-point hunt`,`No-hint review`,`Retention audit`][(number-1)%4]}}
function shuffle(v){let a=[...v];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1)),x=a[i];a[i]=a[j];a[j]=x}return a}
function gameMemScore(mem,skill){let s=mem?.concepts?.[skill]||{},unresolved=Math.max(0,(s.errors||0)-(s.repairCorrect||0)-(s.recoveryCorrect||0)),attempts=s.attempts||0,accuracy=attempts?(s.correct||0)/attempts:1;return unresolved*12+(attempts>=2&&accuracy<.7?8:0)+(attempts===0?2:0)}
function formalScore(skillStats,skill){let s=skillStats?.[skill];if(!s)return 0;let attempts=s.attempted??s.attempts??0,correct=s.correct??0,accuracy=attempts?correct/attempts:1,today=new Date().toISOString().slice(0,10),due=s.due&&String(s.due)<=today;return(due?20:0)+(attempts>=2&&accuracy<.75?12:0)+(s.state===`mastered`&&!due?-3:0)}
function rankCases(pool,mem,skillStats){return shuffle(pool).map((item,index)=>{let scores=item.errors.map(err=>gameMemScore(mem,err.skill)+formalScore(skillStats,err.skill));return{item,score:Math.max(...scores,0),index}}).sort((a,b)=>b.score-a.score||a.index-b.index).map(x=>x.item)}
function trainingPool(level){if(level===1)return CASES.filter(x=>x.subject===`french`&&x.errors.length===1);if(level===2)return CASES.filter(x=>x.subject===`latin`&&x.errors.length===1);if(level===3)return CASES.filter(x=>[`french`,`latin`].includes(x.subject));if(level===4)return CASES.filter(x=>x.subject===`physics`&&x.errors.length===1);if(level===5)return CASES.filter(x=>x.subject===`chemistry`&&x.errors.length===1);if(level===6)return CASES.filter(x=>[`physics`,`chemistry`].includes(x.subject));if(level<=8)return CASES.filter(x=>x.errors.length<=2);if(level<=10)return CASES.filter(x=>x.errors.length>=2||[`physics`,`chemistry`].includes(x.subject));return CASES}
function spotChoices(item,found){let unresolved=item.errors.filter((_,i)=>!found.includes(i)).map(e=>e.wrong),tokens=String(item.student).replace(/[;,]/g,` `).split(/\s+/).map(x=>x.trim()).filter(Boolean),decoys=tokens.filter(tok=>!item.errors.some(e=>e.wrong.includes(tok))&&!unresolved.includes(tok));return shuffle([...unresolved,...shuffle([...new Set(decoys)]).slice(0,Math.max(2,5-unresolved.length))]).slice(0,5)}
function fixChoices(item,err,tier){let all=CASES.filter(x=>x.subject===item.subject).flatMap(x=>x.errors).filter(x=>x.correct!==err.correct),same=all.filter(x=>x.kind===err.kind).map(x=>x.correct),fallback=all.map(x=>x.correct),count=tier>=4?5:4,pool=[...new Set([...shuffle(same),...shuffle(fallback)])];return shuffle([err.correct,...pool.slice(0,count-1)])}
function stars(correct,total){if(!total)return 0;let q=correct/total;return q>=.9?3:q>=.8?2:q>=.6?1:0}
function weekKey(){let d=new Date(),off=(d.getDay()+6)%7;d.setHours(12,0,0,0);d.setDate(d.getDate()-off);return d.toISOString().slice(0,10)}
